package app.studyforge.mobile;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Trusted host + opaque iframe. No JavaScriptInterface, file access or remote requests. */
public final class FeatureActivity extends Activity {
    StudyApp app;WebView web;WebMessagePort port;JSONObject launch;Button apply;TextView status;Handler timer=new Handler(Looper.getMainLooper());boolean ready=false,waiting=false,destroyed=false;int requests=0,events=0;long aiToken=-1,eventWindow=0;
    static final String ORIGIN="https://features.studyforge.local";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);app=(StudyApp)getApplication();try{launch=app.features.launch(getIntent().getStringExtra("id"),getIntent().getBooleanExtra("preview",false));}catch(Exception e){app.notice(e.getMessage());finish();return;}
        LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);ScreenInsets.apply(layout,0);LinearLayout bar=new LinearLayout(this);Button close=new Button(this);close.setText("닫기");close.setOnClickListener(v->finish());bar.addView(close);status=new TextView(this);status.setText(launch.optBoolean("preview")?"새 기능 미리보기 · 검사 중":"내 기능");bar.addView(status,new LinearLayout.LayoutParams(0,-2,1));apply=new Button(this);apply.setText("이 기능 적용");apply.setEnabled(false);apply.setVisibility(launch.optBoolean("preview")?android.view.View.VISIBLE:android.view.View.GONE);apply.setOnClickListener(v->confirmApply());bar.addView(apply);layout.addView(bar);web=new WebView(this);layout.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);
        WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setBlockNetworkLoads(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportMultipleWindows(false);settings.setJavaScriptCanOpenWindowsAutomatically(false);
        if(Build.VERSION.SDK_INT>=29)web.setWebViewRenderProcessClient(new WebViewRenderProcessClient(){@Override public void onRenderProcessResponsive(WebView v,WebViewRenderProcess renderer){}@Override public void onRenderProcessUnresponsive(WebView v,WebViewRenderProcess renderer){if(renderer!=null)renderer.terminate();}});
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();String name=u.getPath();if(!ORIGIN.equals(u.getScheme()+"://"+u.getHost())||!("/feature-host.html".equals(name)||"/feature-host.js".equals(name)))return blocked();try{WebResourceResponse response=new WebResourceResponse(name.endsWith(".js")?"text/javascript":"text/html","UTF-8",getAssets().open(name.substring(1)));response.setResponseHeaders(Map.of("Cache-Control","no-store","Content-Security-Policy","default-src 'none'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; frame-src 'self'; img-src data:; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"));return response;}catch(Exception e){return blocked();}}
            @Override public void onPageFinished(WebView v,String url){if(!url.equals(ORIGIN+"/feature-host.html")||port!=null)return;WebMessagePort[] ports=web.createWebMessageChannel();port=ports[0];port.setWebMessageCallback(new WebMessagePort.WebMessageCallback(){@Override public void onMessage(WebMessagePort p,WebMessage m){try{message(FeatureWire.parse(m.getData()));}catch(Exception e){status.setText(e.getMessage());}}});web.postWebMessage(new WebMessage("studyforge.feature-port",new WebMessagePort[]{ports[1]}),Uri.parse(ORIGIN));}
            @Override public boolean onRenderProcessGone(WebView v,RenderProcessGoneDetail detail){app.notice("개인 기능 실행이 중단됐습니다. 기본 학습실로 돌아왔어요. 기능을 말로 수정하거나 이전 판으로 되돌릴 수 있습니다.");finish();return true;}
        });web.loadUrl(ORIGIN+"/feature-host.html");timer.postDelayed(()->{if(!ready&&!destroyed){app.notice("기능이 제때 시작되지 않았습니다. 기본 학습실은 유지됩니다. 변경안을 수정해 다시 시도하세요.");if(Build.VERSION.SDK_INT>=29&&web.getWebViewRenderProcess()!=null)web.getWebViewRenderProcess().terminate();finish();}},20000);
    }
    static WebResourceResponse blocked(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
    void send(JSONObject data){if(!destroyed&&port!=null)port.postMessage(new WebMessage(data.toString()));}
    void message(JSONObject m) throws Exception {String type=m.getString("type");String owner=launch.getString("owner"),dataset=launch.getString("dataset");synchronized(app){app.features.guard(owner,dataset);}if(type.equals("ready")){JSONObject payload=Json.copy(launch);payload.remove("owner");send(Json.object("type","load","payload",payload));return;}
        if(type.equals("checks")){ready=true;app.features.checks(launch,m.getJSONObject("payload"));boolean passed=m.getJSONObject("payload").optBoolean("passed");apply.setEnabled(passed&&launch.optBoolean("preview"));status.setText(passed?"실행 검사 통과 · 직접 동작도 확인하세요":"실행 검사 실패 · 요청을 보완해 수정하세요");return;}
        if(type.equals("error")){ready=true;apply.setEnabled(false);String error=m.optString("message");status.setText("실행 오류: "+error.substring(0,Math.min(error.length(),300)));if(launch.optBoolean("preview"))app.features.checks(launch,Json.object("rows",Json.array(Json.object("name","실행 오류","passed",false,"error",error))));return;}
        if(System.currentTimeMillis()-eventWindow>60000){eventWindow=System.currentTimeMillis();events=0;}String requestId=m.getString("id");if(++events>120){reply(requestId,null,"기능 요청이 너무 빠릅니다. 잠시 뒤 시도하세요.");return;}if(!requestId.matches("[a-zA-Z0-9_-]{1,80}"))throw new Exception("기능 요청 형식을 확인하세요.");JSONObject payload=m.optJSONObject("payload");if(payload==null)payload=new JSONObject();try{switch(type){
            case "save" -> {JSONObject value=app.features.saveData(launch,payload.getJSONObject("value"));reply(requestId,value,null);}
            case "practice" -> {app.features.practice(launch,payload.getJSONArray("ids"));reply(requestId,true,null);finish();}
            case "ask" -> ask(requestId,payload.getString("prompt"));
            default -> reply(requestId,null,"지원하지 않는 기능 요청입니다.");
        }}catch(Exception e){reply(requestId,null,e.getMessage());}
    }
    void reply(String id,Object result,String error){try{send(Json.object("type","result","id",id,"value",result,"error",error));}catch(Exception ignored){}}
    void ask(String id,String prompt) throws Exception {if(launch.optBoolean("preview")||!FeatureProgram.permits(launch.getJSONObject("feature").getJSONObject("program"),"ai.request"))throw new Exception("미리보기에서는 실제 AI 요청을 보내지 않습니다.");if(prompt.length()<1||prompt.length()>8000||waiting||requests>=10)throw new Exception("요청은 8천 자까지, 한 번에 하나씩 보낼 수 있습니다. 이 실행에서는 최대 10회입니다.");if(app.busy)throw new Exception("현재 작업을 마친 뒤 요청하세요.");String model=app.selectedModel(Json.object("model",app.workspace.optString("model",app.models.length()==0?"":app.models.getJSONObject(0).getString("slug"))));waiting=true;new AlertDialog.Builder(this).setTitle("내 ChatGPT에 요청할까요?").setMessage("선택 모델: "+model+"\n본인 구독 사용량을 사용하며 아래 내용을 OpenAI로 보냅니다.\n\n"+prompt).setNegativeButton("취소",(d,w)->{waiting=false;reply(id,null,"사용자가 AI 요청을 취소했습니다.");}).setOnCancelListener(d->{waiting=false;reply(id,null,"사용자가 AI 요청을 취소했습니다.");}).setPositiveButton("이 내용으로 요청",(d,w)->{try{startAi(id,prompt,model);}catch(Exception e){waiting=false;reply(id,null,e.getMessage());}}).show();}
    void startAi(String id,String prompt,String model) throws Exception {final String owner=launch.getString("owner"),dataset=launch.getString("dataset");final long token;synchronized(app){app.features.guard(owner,dataset);if(app.busy)throw new Exception("현재 작업을 마친 뒤 요청하세요.");requests++;app.busy=true;token=++app.job;aiToken=token;JobService.begin(app,"개인 기능의 AI 요청을 처리합니다.");}app.worker.execute(()->{try{String result=Api.responses(StudyGenerator.request(model,"사용자가 만든 학습 기능의 요청에 한국어로 답하라. 제공된 정보로 판단할 수 없는 내용과 추론을 구분한다. 근거 없는 정답·교수 지시·출처를 만들지 않는다. 외부 검색은 수행하지 못한다. 실행 코드 대신 요청한 학습 내용만 반환한다.",Json.array(Json.object("type","input_text","text",prompt))),app.connection.accessToken(),app::progress);synchronized(app){app.checkJob(token,owner);app.features.guard(owner,dataset);}runOnUiThread(()->reply(id,result,null));}catch(Exception e){runOnUiThread(()->reply(id,null,e.getMessage()));}finally{synchronized(app){if(token==app.job){app.busy=false;app.state();JobService.end(app);}}waiting=false;}});}
    void confirmApply(){try{JSONObject patch=launch.getJSONObject("feature").getJSONObject("program").getJSONObject("hostPatch");new AlertDialog.Builder(this).setTitle("이 기능을 적용할까요?").setMessage("기능을 추가·개정하고 아래 기본 설정 변경을 함께 적용합니다. 문제·풀이 기록은 유지합니다.\n\n"+FeatureProgram.patchSummary(patch)).setNegativeButton("취소",null).setPositiveButton("적용",(d,w)->app.worker.execute(()->{try{app.features.install(launch.getJSONObject("feature").getString("id"),launch.getJSONObject("feature").getString("hash"),launch.getString("owner"));runOnUiThread(this::finish);}catch(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}})).show();}catch(Exception e){status.setText(e.getMessage());}}
    @Override protected void onResume(){super.onResume();if(launch!=null)try{synchronized(app){app.features.guard(launch.getString("owner"),launch.getString("dataset"));}}catch(Exception e){finish();}}
    @Override protected void onDestroy(){destroyed=true;timer.removeCallbacksAndMessages(null);if(aiToken==app.job&&app.busy)app.cancel();if(port!=null)port.close();if(web!=null){((android.view.ViewGroup)web.getParent()).removeView(web);web.destroy();}super.onDestroy();}
}
